class CtxPorts(TextualConvention, Unsigned32):
    description = 'A port is the media session port allocation for a resource. It\n        is commonly referred to as a media video RTP stream for a\n        multipoint switch and an audio RTP steam for ISDN/IVR. It is\n        also known as a segment or screen.  A Cisco TelePresence System\n        1000 uses one port while a Cisco TelePresence System 3000 uses 3\n        ports, one for each video screen.'
    status = 'current'
    displayHint = 'd'
    subtypeSpec = Unsigned32.subtypeSpec + ValueRangeConstraint(1, 65535)

